import sys
import re
import math

def parse_data(data_path):
    data = {}
    with open(data_path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            try:
                name, value_str = line.split('=', 1)
                value = int(value_str)
                data[name] = value
            except ValueError:
                continue
    return data

def evaluate_expression(expr, variables):
    try:
        # Replace variables with their values and evaluate safely
        safe_expr = expr
        for var in variables:
            safe_expr = safe_expr.replace(var, str(variables[var]))
        # Use eval with a restricted globals and locals to prevent arbitrary code execution
        # We only allow basic arithmetic operations and the variables we have
        allowed_globals = {'__builtins__': None}
        allowed_locals = {}
        # Add variables to locals
        for var in variables:
            allowed_locals[var] = variables[var]
        # Evaluate the expression
        result = eval(safe_expr, allowed_globals, allowed_locals)
        return result
    except:
        return 0

def render_template(template_path, data, output_path):
    with open(template_path, 'r') as f:
        template = f.read()

    # Find all placeholders and evaluate their expressions
    pattern = re.compile(r'\{\{([^}]+)\}\}')
    placeholders = pattern.findall(template)
    for placeholder in placeholders:
        expr = placeholder.strip()
        value = evaluate_expression(expr, data)
        # Format the value as specified
        if value == int(value):
            formatted_value = str(int(value))
        else:
            formatted_value = "{:.2f}".format(value)
        # Replace the placeholder with the formatted value
        template = template.replace('{{' + placeholder + '}}', formatted_value)

    with open(output_path, 'w') as f:
        f.write(template)

