    if len(sys.argv) != 4:
        sys.exit(1)
    template_path = sys.argv[1]
    data_path = sys.argv[2]
    output_path = sys.argv[3]

    data = parse_data(data_path)
    render_template(template_path, data, output_path)

if __name__ == "__main__":
    main()

